"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { 
  Film, 
  Layers, 
  Settings, 
  BarChart3, 
  ShieldCheck, 
  MonitorPlay,
  Radio,
  Monitor,
  LogOut,
  LogIn
} from "lucide-react";
import { useState, useEffect } from "react";

export function Sidebar() {
  const pathname = usePathname();
  const router = useRouter();
  const [currentUser, setCurrentUser] = useState<any>(null);

  useEffect(() => {
    try {
      const stored = localStorage.getItem("user");
      if (stored) setCurrentUser(JSON.parse(stored));
    } catch (e) {}
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("user");
    setCurrentUser(null);
    router.push("/login");
  };

  const navItems = [
    { href: "/", label: "Tổng quan (Dashboard)", icon: BarChart3 },
    { href: "/production", label: "Sản xuất Video AI", icon: Film, badge: "Live" },
    { href: "/channels", label: "Quản lý Kênh", icon: Layers },
    { href: "/config", label: "Cấu hình AI & Engine", icon: Settings },
    { href: "/analytics", label: "Phân tích Hiệu quả", icon: BarChart3 },
    { href: "/ip-manager", label: "Quản lý IP Admin", icon: ShieldCheck },
    { href: "/rustdesk", label: "Cấu hình RustDesk", icon: Monitor },
  ];

  return (
    <aside className="w-64 border-r border-[var(--vc-border)] bg-[var(--vc-card-bg)] backdrop-blur-xl flex flex-col justify-between p-4 min-h-screen sticky top-0">
      {/* Brand Header */}
      <div>
        <div className="flex items-center gap-3 pb-4 mb-4 border-b border-[var(--vc-border)]">
          <div className="w-10 h-10 rounded-xl flex items-center justify-center bg-gradient-to-br from-[#C2542D] to-[#C99A45] shadow-lg shadow-[#C2542D]/20">
            <MonitorPlay className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="font-extrabold text-lg leading-tight gradient-text">
              VideoCrew
            </h1>
            <span className="text-xs text-[var(--vc-muted)] font-medium">Studio v2.0 Next.js</span>
          </div>
        </div>

        {/* Navigation Menu */}
        <nav className="space-y-1">
          <div className="text-[10px] uppercase font-bold tracking-wider text-[var(--vc-muted)] px-3 mb-2">
            Menu Điều Hướng
          </div>
          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = pathname === item.href;
            return (
              <Link
                key={item.href}
                href={item.href}
                className={`flex items-center justify-between px-3 py-2 rounded-xl font-medium text-xs transition-all duration-200 ${
                  isActive
                    ? "bg-[var(--vc-accent-soft)] text-[#C2542D] border border-[var(--vc-accent-soft-strong)] shadow-sm font-bold"
                    : "text-zinc-400 hover:text-zinc-200 hover:bg-white/[0.04]"
                }`}
              >
                <div className="flex items-center gap-2.5">
                  <Icon className={`w-4 h-4 ${isActive ? "text-[#C2542D]" : "text-zinc-400"}`} />
                  <span>{item.label}</span>
                </div>
                {item.badge && (
                  <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full bg-[#C2542D] text-white animate-pulse">
                    {item.badge}
                  </span>
                )}
              </Link>
            );
          })}
        </nav>
      </div>

      {/* Account / Engine Status Card */}
      <div className="space-y-3 mt-4">
        <div className="glass-panel p-3 border-[var(--vc-border)]">
          <div className="flex items-center justify-between mb-1.5">
            <span className="text-[11px] font-semibold text-zinc-300 flex items-center gap-1.5">
              <Radio className="w-3 h-3 text-emerald-400 animate-ping" />
              FastAPI Server
            </span>
            <span className="vc-badge text-[9px] py-0 px-1.5">Online</span>
          </div>
          <div className="text-[10px] text-[var(--vc-muted)] space-y-0.5 border-t border-[var(--vc-border)] pt-1.5 mt-1">
            <div className="flex justify-between">
              <span>Người dùng:</span>
              <span className="font-semibold text-zinc-200">
                {currentUser?.username || "Admin Guest"}
              </span>
            </div>
            <div className="flex justify-between">
              <span>Client IP:</span>
              <span className="font-mono text-zinc-300">127.0.0.1</span>
            </div>
          </div>
        </div>

        {currentUser ? (
          <button
            onClick={handleLogout}
            className="w-full flex items-center justify-center gap-2 py-2 rounded-xl text-xs font-semibold text-zinc-400 hover:text-red-400 bg-white/[0.03] hover:bg-red-500/10 border border-white/5 transition"
          >
            <LogOut className="w-3.5 h-3.5" />
            Đăng Xuất
          </button>
        ) : (
          <Link
            href="/login"
            className="w-full flex items-center justify-center gap-2 py-2 rounded-xl text-xs font-semibold text-zinc-300 hover:text-white bg-white/[0.05] hover:bg-white/[0.08] border border-white/10 transition"
          >
            <LogIn className="w-3.5 h-3.5 text-[#C2542D]" />
            Đăng Nhập / Đăng Ký
          </Link>
        )}
      </div>
    </aside>
  );
}
