"use client";

import { useEffect, useState } from "react";
import { usePathname, useRouter } from "next/navigation";
import { Sidebar } from "./Sidebar";

export function AuthGuard({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);

  const isLoginPage = pathname ? (pathname === "/login" || pathname === "/login/" || pathname.startsWith("/login")) : false;

  useEffect(() => {
    try {
      const user = localStorage.getItem("user");
      if (!user) {
        setIsAuthenticated(false);
        if (!isLoginPage) {
          router.replace("/login");
        }
      } else {
        setIsAuthenticated(true);
        if (isLoginPage) {
          router.replace("/");
        }
      }
    } catch (e) {
      setIsAuthenticated(false);
    }
  }, [pathname, isLoginPage, router]);

  // Loading check session
  if (isAuthenticated === null) {
    return (
      <div className="min-h-screen w-full flex items-center justify-center bg-[#0f1117] text-zinc-400 font-medium text-sm">
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 border-2 border-[#C2542D] border-t-transparent rounded-full animate-spin" />
          Đang xác thực bảo mật...
        </div>
      </div>
    );
  }

  // Nếu đang ở trang login, luôn render form login
  if (isLoginPage) {
    return <main className="flex-1 w-full min-h-screen flex items-center justify-center">{children}</main>;
  }

  // Nếu chưa đăng nhập và không phải trang login
  if (!isAuthenticated) {
    return null;
  }

  // Đã đăng nhập -> Render đầy đủ Sidebar và nội dung
  return (
    <>
      <Sidebar />
      <main className="flex-1 p-8 overflow-y-auto max-w-7xl mx-auto w-full">
        {children}
      </main>
    </>
  );
}
